const items = [];
for (const [hw, topics, list] of GROUPS) {
  const hwId = `vocab:${slug(hw)}`;
  list.forEach(([pattern, display, primary, alts, meaningVi, bandTarget, register, traps, example], idx) => {
    const phrase = display.replace('___', primary);
    const colId = `col:${slug(hw)}_${slug(phrase)}`;
    const answers = [primary, ...alts];
    // Fix minor typo if any ("an negligible" -> "a negligible")
    const cleanPhrase = phrase.replace(/\ban negligible\b/g, 'a negligible');
    const cleanDisplay = display.replace(/\ban ___ impact on\b/, primary === 'negligible' ? 'a ___ impact on' : display);
    const cleanExample = example.replace(/\ban negligible\b/g, 'a negligible');
    items.push({
      id: colId,
      headwordId: hwId,
      pattern,
      phrase: cleanPhrase,
      gaps: [{ display: cleanDisplay, answers, primary }],
      meaningVi,
      example: cleanExample,
      register,
      bandTarget,
      l1Traps: traps.map(([wrong, whyVi]) => ({ wrong, whyVi })),
      topics,
      provenance: {
        createdBy: 'llm+review',
        source: 'llm:gemini@2026-11-20',
        license: 'own',
        qa: { schema: 'pass', verifier: 'pass' },
      },
    });
  });
}

fs.mkdirSync(path.dirname(OUT), { recursive: true });
fs.writeFileSync(OUT, JSON.stringify(items, null, 2) + '\n', 'utf8');
console.log(`[author_collocations_part1] Wrote ${items.length} collocations across ${GROUPS.length} headwords -> batch_001.json`);
